 p_id=>wwv_flow_imp.id(9685154711996301)
,p_plug_name=>'New'
,p_static_id=>'new'
,p_title=>'Projects under monitoring'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2102002977963900996
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT p.id,',
'       p.name,',
'       p.region,',
'       p.simulation_status,',
'       (SELECT COUNT(DISTINCT o.period_key)',
'          FROM observations o',
'         WHERE o.project_id = p.id AND o.metric = ''ndvi_mean'') AS periods,',
'       (SELECT ROUND(MAX(o2.value), 4)',
'          FROM observations o2',
'         WHERE o2.project_id = p.id AND o2.metric = ''ndvi_mean''',
'           AND o2.period_key = (SELECT MAX(o3.period_key)',
'                                  FROM observations o3',
'                                 WHERE o3.project_id = p.id',
'                                   AND o3.metric = ''ndvi_mean''',
'                                   AND o3.value IS NOT NULL)) AS latest_ndvi,',
'       (SELECT COUNT(*) FROM alerts a',
'         WHERE a.project_id = p.id AND a.status = ''open'') AS open_alerts',
'FROM projects p',
'ORDER BY open_alerts DESC, p.name'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_content_disposition=>'ATTACHMENT'
,p_prn_units=>'INCHES'
