'SELECT event_type                                 AS event,',
'       SUBSTR(manifest_sha256, 1, 12) || ''...''    AS manifest_hash,',
'       CASE WHEN previous_event_sha256 IS NULL',
'            THEN ''first in chain''',
'            ELSE SUBSTR(previous_event_sha256, 1, 12) || ''...''',
'       END                                        AS links_to,',
'       anchor_status                              AS anchor,',
'       SUBSTR(tx_hash, 1, 14) || ''...''            AS transaction,',
'       ''<a href="'' || explorer_url || ''" target="_blank" rel="noopener">View on explorer</a>''',
